"""settings_table.py (GENERATED by scripts/settings_gen.py, #67): sane rows; the generator agrees with the clean tree."""
import os
import subprocess
import sys
from pathlib import Path

import pytest

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "scripts"))
import settings_cli as C  # noqa: E402
import settings_table as T  # noqa: E402

RTDFW = Path(os.environ.get("AWTO_RTDFW_REPO", "/mnt/2tb/git/awto-rtdfw"))


def test_rows_sane():
    ids = [r["id"] for r in T.ROWS]
    assert len(ids) == len(set(ids)) and all(1 <= i <= 255 for i in ids)
    for r in T.ROWS:
        assert r["min"] <= r["default"] <= r["max"], r["name"]
        if r["type"] == "enum":
            assert len(r["options"]) == r["max"] - r["min"] + 1, r["name"]
    assert T.BY_NAME["factory_reset"]["vcp"] == 0x04


def test_power_levels_and_recovery_rows_present():
    for n in ("pwr_l1_en", "pwr_l1_ms", "pwr_l2_s", "pwr_l3_s", "wake_d1", "wake_d3", "debug_link", "panel_t3", "logo_ms"):
        assert n in T.BY_NAME


def test_parse_value():
    assert C.parse_value(T.BY_NAME["gamma"], "2.2") == 3
    assert C.parse_value(T.BY_NAME["logo"], "off") == 0
    with pytest.raises(SystemExit):
        C.parse_value(T.BY_NAME["panel_t3"], "10")         # below the validated range


@pytest.mark.skipif(not (RTDFW / "settings/registry.tsv").exists() or not (RTDFW / "awto/settings/set_table.c").exists(),
                    reason="clean tree without the settings module")
def test_generated_files_current():
    r = subprocess.run([sys.executable, str(ROOT / "scripts/settings_gen.py"), "--rtdfw", str(RTDFW), "--check"],
                       capture_output=True, text=True, timeout=60)
    assert r.returncode == 0, r.stdout + r.stderr
